body {
  margin: 0;
  height: 100vh;
  background: linear-gradient(45deg, #0f0c29, #302b63, #24243e);
  background-size: 400% 400%;
  animation: FunkGroove 2s ease-in-out infinite alternate, BassPulse 0.5s infinite alternate;
  color: #fff;
  font-family: 'Inter', sans-serif;
  overflow: hidden;
}

@keyframes FunkGroove {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; filter: hue-rotate(45deg); }
  100% { background-position: 0% 50%; filter: hue-rotate(90deg); }
}

@keyframes BassPulse {
  0% { transform: scale(1); box-shadow: inset 0 0 50px rgba(255, 0, 150, 0.2); }
  100% { transform: scale(1.01); box-shadow: inset 0 0 150px rgba(0, 255, 255, 0.6); }
}

p, div {
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.8), 0 0 20px rgba(255, 0, 255, 0.6);
  animation: TextBounce 1s infinite alternate ease-in-out;
}

@keyframes TextBounce {
  0% { transform: translateY(0px); }
  100% { transform: translateY(-2px); }
}
